// ============================================================================
// Cloudflare Worker: avero-media-proxy
// ----------------------------------------------------------------------------
// Proxies GET requests to a private Backblaze B2 bucket (avero-media) using
// a dedicated READ-ONLY application key. This enables free egress via the
// Backblaze/Cloudflare Bandwidth Alliance.
//
// The Worker verifies a short-lived HMAC token (generated by media-storage)
// to enforce the same 1-hour expiry as the original presigned URLs. This
// prevents indefinite access to file keys if they are leaked.
//
// Token format: base64url(expires_at).base64url(hmac_sha256(expires_at + "." + file_key))
// The media-storage Edge Function and this Worker share the MEDIA_WORKER_TOKEN_KEY secret.
//
// Reference: Backblaze "Deliver Private Backblaze B2 Content Through Cloudflare CDN"
// and backblaze-b2-samples/cloudflare-b2 GitHub repo.
// ============================================================================

import {
  S3Client,
  GetObjectCommand,
  HeadObjectCommand,
} from "@aws-sdk/client-s3";
import { getSignedUrl } from "@aws-sdk/s3-request-presigner";

// ----------------------------------------------------------------------------
// Types
// ----------------------------------------------------------------------------

interface Env {
  // Set via `wrangler secret put`
  B2_KEY_ID: string;
  B2_APPLICATION_KEY: string;
  MEDIA_WORKER_TOKEN_KEY: string;
  // Set in wrangler.toml [vars]
  B2_BUCKET_NAME: string;
  B2_ENDPOINT: string;
}

// ----------------------------------------------------------------------------
// Constants
// ----------------------------------------------------------------------------

const CACHE_CONTROL_IMMUTABLE = "public, max-age=31536000, immutable";
const CACHE_CONTROL_NO_CACHE = "public, max-age=0, must-revalidate";

// Headers to forward from B2 response to client
const FORWARD_RESPONSE_HEADERS = [
  "content-type",
  "content-length",
  "etag",
  "last-modified",
  "accept-ranges",
  "content-disposition",
  "cache-control",
] as const;

// ----------------------------------------------------------------------------
// S3 Client (singleton, reused across requests)
// ----------------------------------------------------------------------------

let s3Client: S3Client | null = null;

function getS3Client(env: Env): S3Client {
  if (s3Client) return s3Client;

  const endpoint = env.B2_ENDPOINT.startsWith("http")
    ? env.B2_ENDPOINT
    : `https://${env.B2_ENDPOINT}`;

  s3Client = new S3Client({
    region: parseRegionFromEndpoint(env.B2_ENDPOINT),
    endpoint,
    credentials: {
      accessKeyId: env.B2_KEY_ID,
      secretAccessKey: env.B2_APPLICATION_KEY,
    },
    forcePathStyle: true,
    // B2 doesn't support the AWS SDK v3.729.0+ default CRC32 checksum flow
    requestChecksumCalculation: "WHEN_REQUIRED",
    responseChecksumValidation: "WHEN_REQUIRED",
  });

  return s3Client;
}

function parseRegionFromEndpoint(endpoint: string): string {
  try {
    const normalized = endpoint.startsWith("http")
      ? endpoint
      : `https://${endpoint}`;
    const host = new URL(normalized).hostname;
    const match = host.match(/^s3\.([^.]+)\.backblazeb2\.com$/i);
    if (match) return match[1];
    const parts = host.split(".");
    if (parts.length >= 2 && parts[0].toLowerCase() === "s3") {
      return parts[1];
    }
  } catch {
    // fall through
  }
  // Default to eu-central-003 if parsing fails (should not happen with valid config)
  return "eu-central-003";
}

// ----------------------------------------------------------------------------
// Token Verification
// ----------------------------------------------------------------------------

const TOKEN_TTL_SECONDS = 60 * 60; // 1 hour, matches DOWNLOAD_URL_TTL_SECONDS in media-storage

/**
 * Verifies the HMAC token from the query string.
 * Token format: base64url(expires_at).base64url(hmac_sha256(expires_at + "." + file_key))
 * Returns the expiresAt timestamp if valid, throws if invalid/expired.
 */
async function verifyToken(
  token: string,
  fileKey: string,
  signingKey: string
): Promise<number> {
  const parts = token.split(".");
  if (parts.length !== 2) {
    throw new Error("Invalid token format");
  }

  const [expiresAtB64, signatureB64] = parts;

  // Decode expires_at
  let expiresAt: number;
  try {
    const expiresAtJson = base64urlDecode(expiresAtB64);
    expiresAt = parseInt(expiresAtJson, 10);
    if (isNaN(expiresAt)) throw new Error("Invalid expires_at");
  } catch {
    throw new Error("Invalid token: malformed expires_at");
  }

  // Check expiry (with 30s clock skew tolerance)
  const now = Math.floor(Date.now() / 1000);
  if (now > expiresAt + 30) {
    throw new Error("Token expired");
  }

  // Verify HMAC signature
  const message = new TextEncoder().encode(`${expiresAt}.${fileKey}`);
  const keyData = new TextEncoder().encode(signingKey);
  const cryptoKey = await crypto.subtle.importKey(
    "raw",
    keyData,
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["verify"]
  );

  const signature = base64urlDecodeToBytes(signatureB64);
  const isValid = await crypto.subtle.verify("HMAC", cryptoKey, signature, message);

  if (!isValid) {
    throw new Error("Invalid token signature");
  }

  return expiresAt;
}

/** Base64URL decode to string. */
function base64urlDecode(str: string): string {
  // Add padding if needed
  const padded = str.replace(/-/g, "+").replace(/_/g, "/");
  const padLength = (4 - (padded.length % 4)) % 4;
  const withPadding = padded + "=".repeat(padLength);
  return atob(withPadding);
}

/** Base64URL decode to Uint8Array. */
function base64urlDecodeToBytes(str: string): Uint8Array {
  const binary = base64urlDecode(str);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes;
}

// ----------------------------------------------------------------------------
// Request Handler
// ----------------------------------------------------------------------------

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    // Only allow GET and HEAD
    if (request.method !== "GET" && request.method !== "HEAD") {
      return new Response("Method Not Allowed", {
        status: 405,
        headers: { Allow: "GET, HEAD" },
      });
    }

    // Extract file_key from path: /{file_key}
    const url = new URL(request.url);
    const fileKey = url.pathname.slice(1); // Remove leading '/'

    if (!fileKey || fileKey.includes("..")) {
      return new Response("Bad Request: Invalid file key", { status: 400 });
    }

    // Validate file_key format (basic sanity check)
    // Expected: {space_id}/{memory_id}/{filename} or avatars/{user_id}/avatar.webp
    if (!isValidFileKey(fileKey)) {
      return new Response("Bad Request: Malformed file key", { status: 400 });
    }

    // Verify token from query string
    const token = url.searchParams.get("token");
    if (!token) {
      return new Response("Unauthorized: Missing token", { status: 401 });
    }

    try {
      await verifyToken(token, fileKey, env.MEDIA_WORKER_TOKEN_KEY);
    } catch (error) {
      console.error("[avero-media-proxy] Token verification failed:", error);
      return new Response("Unauthorized: Invalid or expired token", { status: 401 });
    }

    try {
      const client = getS3Client(env);
      const bucket = env.B2_BUCKET_NAME;

      // For HEAD requests, use HeadObjectCommand (no body)
      // For GET, use GetObjectCommand
      const isHead = request.method === "HEAD";

      // Check if Range header is present (video seeking)
      const rangeHeader = request.headers.get("Range");

      if (isHead) {
        return await handleHeadRequest(client, bucket, fileKey);
      }

      return await handleGetRequest(client, bucket, fileKey, rangeHeader);
    } catch (error) {
      console.error("[avero-media-proxy] Error:", error);
      // Don't leak internal details
      return new Response("Internal Server Error", { status: 500 });
    }
  },
} satisfies ExportedHandler<Env>;

// ----------------------------------------------------------------------------
// HEAD Request Handler
// ----------------------------------------------------------------------------

async function handleHeadRequest(
  client: S3Client,
  bucket: string,
  fileKey: string
): Promise<Response> {
  const command = new HeadObjectCommand({ Bucket: bucket, Key: fileKey });

  try {
    const response = await client.send(command);
    return new Response(null, {
      status: 200,
      headers: buildResponseHeaders(response),
    });
  } catch (error: any) {
    if (error.name === "NotFound" || error.$metadata?.httpStatusCode === 404) {
      return new Response("Not Found", { status: 404 });
    }
    if (error.name === "Forbidden" || error.$metadata?.httpStatusCode === 403) {
      return new Response("Forbidden", { status: 403 });
    }
    throw error;
  }
}

// ----------------------------------------------------------------------------
// GET Request Handler
// ----------------------------------------------------------------------------

async function handleGetRequest(
  client: S3Client,
  bucket: string,
  fileKey: string,
  rangeHeader: string | null
): Promise<Response> {
  const command = new GetObjectCommand({
    Bucket: bucket,
    Key: fileKey,
    Range: rangeHeader || undefined,
  });

  try {
    const response = await client.send(command);

    if (!response.Body) {
      return new Response("Not Found", { status: 404 });
    }

    // Convert ReadableStream to Web Stream
    const body = response.Body as unknown as ReadableStream<Uint8Array>;

    const headers = buildResponseHeaders(response);

    // For Range requests, ensure we return 206 Partial Content
    const status = rangeHeader ? 206 : 200;

    return new Response(body, {
      status,
      headers,
    });
  } catch (error: any) {
    if (error.name === "NotFound" || error.$metadata?.httpStatusCode === 404) {
      return new Response("Not Found", { status: 404 });
    }
    if (error.name === "Forbidden" || error.$metadata?.httpStatusCode === 403) {
      return new Response("Forbidden", { status: 403 });
    }
    if (error.name === "InvalidRange" || error.$metadata?.httpStatusCode === 416) {
      return new Response("Range Not Satisfiable", { status: 416 });
    }
    throw error;
  }
}

// ----------------------------------------------------------------------------
// Header Building
// ----------------------------------------------------------------------------

function buildResponseHeaders(
  s3Response: {
    ContentType?: string;
    ContentLength?: number;
    ETag?: string;
    LastModified?: Date;
    AcceptRanges?: string;
    ContentDisposition?: string;
    CacheControl?: string;
  }
): Headers {
  const headers = new Headers();

  // Forward relevant headers from B2
  if (s3Response.ContentType) headers.set("Content-Type", s3Response.ContentType);
  if (s3Response.ContentLength !== undefined)
    headers.set("Content-Length", String(s3Response.ContentLength));
  if (s3Response.ETag) headers.set("ETag", s3Response.ETag);
  if (s3Response.LastModified)
    headers.set("Last-Modified", s3Response.LastModified.toUTCString());
  if (s3Response.AcceptRanges)
    headers.set("Accept-Ranges", s3Response.AcceptRanges);
  if (s3Response.ContentDisposition)
    headers.set("Content-Disposition", s3Response.ContentDisposition);

  // Set Cache-Control: immutable for media files (they're addressed by UUID, never change)
  // Override any Cache-Control from B2
  headers.set("Cache-Control", CACHE_CONTROL_IMMUTABLE);

  // CORS: Allow all origins for media consumption (Worker is the CDN edge)
  // The actual authorization happened at URL generation time in media-storage
  headers.set("Access-Control-Allow-Origin", "*");
  headers.set("Access-Control-Allow-Methods", "GET, HEAD");
  headers.set("Access-Control-Allow-Headers", "Range");
  headers.set("Access-Control-Expose-Headers", "Content-Length, Content-Range, Accept-Ranges, ETag");

  return headers;
}

// ----------------------------------------------------------------------------
// File Key Validation
// ----------------------------------------------------------------------------

function isValidFileKey(key: string): boolean {
  // Basic validation: no path traversal, reasonable segments
  if (key.includes("..") || key.startsWith("/") || key.endsWith("/")) {
    return false;
  }

  const segments = key.split("/");
  if (segments.length < 2) return false;

  // Check each segment for safe characters
  const safeSegmentRe = /^[a-zA-Z0-9._-]+$/;
  for (const segment of segments) {
    if (!safeSegmentRe.test(segment)) return false;
  }

  // Two valid patterns:
  // 1. avatars/{user_id}/avatar.webp (exactly 3 segments)
  // 2. {space_id}/{memory_id}/{filename} (at least 3 segments)
  if (segments[0] === "avatars") {
    return (
      segments.length === 3 &&
      segments[2] === "avatar.webp" &&
      isUuid(segments[1])
    );
  }

  // Space media: {space_id}/{memory_id}/{filename}
  return segments.length >= 3 && isUuid(segments[0]) && isUuid(segments[1]);
}

function isUuid(value: string): boolean {
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(value);
}